     1→import { useEffect, useCallback, useRef } from "react";
     2→import { useUiStore, useAppStore, useWorkspaceStore } from "@/stores";
     3→import { useTabStore } from "@/stores/tab-store";
     4→import { createStackForLocation } from "@/navigation/location-navigation";
     5→import { createTabNavigationState } from "@/navigation/tab-navigation";
     6→
     7→/**
     8→ * Parse a shortcut string like "Shift+Cmd+J" into components.
     9→ */
    10→export function parseShortcut(shortcut: string): {
    11→  ctrl: boolean;
    12→  meta: boolean;
    13→  shift: boolean;
    14→  alt: boolean;
    15→  key: string;
    16→} {
    17→  const parts = shortcut.toLowerCase().split("+");
    18→  const key = parts[parts.length - 1];
    19→  return {
    20→    ctrl: parts.includes("ctrl"),
    21→    meta: parts.includes("cmd") || parts.includes("meta"),
    22→    shift: parts.includes("shift"),
    23→    alt: parts.includes("alt") || parts.includes("option"),
    24→    key,
    25→  };
    26→}
    27→
    28→/**
    29→ * Check if a keyboard event matches a shortcut configuration.
    30→ */
    31→export function matchesShortcut(e: Pick<KeyboardEvent, "key" | "ctrlKey" | "metaKey" | "shiftKey" | "altKey">, shortcut: string): boolean {
    32→  if (!shortcut) return false;
    33→
    34→  const parsed = parseShortcut(shortcut);
    35→
    36→  // For modifier keys (Ctrl/Cmd), we check if either is pressed
    37→  // This allows cross-platform shortcuts to work
    38→  const modifierMatch =
    39→    (parsed.ctrl || parsed.meta)
    40→      ? (e.ctrlKey || e.metaKey)
    41→      : (!e.ctrlKey && !e.metaKey);
    42→
    43→  const shiftMatch = parsed.shift ? e.shiftKey : !e.shiftKey;
    44→  const altMatch = parsed.alt ? e.altKey : !e.altKey;
    45→  const keyMatch = e.key.toLowerCase() === parsed.key;
    46→
    47→  return modifierMatch && shiftMatch && altMatch && keyMatch;
    48→}
    49→
    50→export function isShortcutPressed(
    51→  e: Pick<KeyboardEvent, "key" | "ctrlKey" | "metaKey" | "shiftKey" | "altKey">,
    52→  shortcut: string
    53→): boolean {
    54→  return matchesShortcut(e, shortcut);
    55→}
    56→
    57→export function getTabSwitchIndexFromShortcut(
    58→  e: Pick<KeyboardEvent, "key" | "ctrlKey" | "metaKey" | "shiftKey" | "altKey">
    59→): number | null {
    60→  if (!(e.metaKey || e.ctrlKey) || e.shiftKey || e.altKey) {
    61→    return null;
    62→  }
    63→
    64→  if (!/^[1-9]$/.test(e.key)) {
    65→    return null;
    66→  }
    67→
    68→  return Number(e.key) - 1;
    69→}
    70→
    71→export type EditableTargetLike = {
    72→  tagName?: string | null;
    73→  isContentEditable?: boolean;
    74→  getAttribute?: (name: string) => string | null;
    75→  closest?: (selector: string) => unknown;
    76→};
    77→
    78→export function isEditableShortcutTarget(
    79→  target: EventTarget | EditableTargetLike | null
    80→): boolean {
    81→  const element = target as EditableTargetLike | null;
    82→  if (!element) return false;
    83→
    84→  const tagName = element.tagName?.toUpperCase();
    85→  if (tagName === "INPUT" || tagName === "TEXTAREA" || tagName === "SELECT") {
    86→    return true;
    87→  }
    88→
    89→  if (element.isContentEditable) {
    90→    return true;
    91→  }
    92→
    93→  if (element.getAttribute?.("role") === "textbox") {
    94→    return true;
    95→  }
    96→
    97→  try {
    98→    return Boolean(
    99→      element.closest?.(
   100→        'input, textarea, select, [contenteditable=""], [contenteditable="true"], [contenteditable], [role="textbox"]'
   101→      )
   102→    );
   103→  } catch {
   104→    return false;
   105→  }
   106→}
   107→
   108→/**
   109→ * Global keyboard shortcuts for the application.
   110→ *
   111→ * Registered shortcuts (configurable in Settings > Shortcuts):
   112→ * - createTask: Open create task dialog (default: Shift+Cmd+J)
   113→ */
   114→export function useGlobalShortcuts() {
   115→  const openCreateTaskDialog = useUiStore((state) => state.openCreateTaskDialog);
   116→  const shortcuts = useAppStore((state) => state.shortcuts);
   117→  const activeWorkspaceId = useWorkspaceStore((state) => state.activeWorkspaceId);
   118→  const openTab = useTabStore((state) => state.openTab);
   119→  const closeTab = useTabStore((state) => state.closeTab);
   120→  const setActiveTab = useTabStore((state) => state.setActiveTab);
   121→  const reopenClosedTab = useTabStore((state) => state.reopenClosedTab);
   122→
   123→  // Read tab state via ref to avoid recreating the callback on every tab change.
   124→  // Using .map() in a zustand selector creates a new array each time, which
   125→  // triggers infinite re-renders via useSyncExternalStore.
   126→  const tabStateRef = useRef({ activeTabId: null as string | null, tabIds: [] as string[], tabCount: 0 });
   127→  const activeTabId = useTabStore((state) => state.activeTabId);
   128→  const tabs = useTabStore((state) => state.tabs);
   129→  tabStateRef.current = {
   130→    activeTabId,
   131→    tabIds: tabs.map((tab) => tab.id),
   132→    tabCount: tabs.length,
   133→  };
   134→
   135→  const handleKeyDown = useCallback(
   136→    (e: KeyboardEvent) => {
   137→      // Create Task shortcut
   138→      if (matchesShortcut(e, shortcuts.createTask)) {
   139→        e.preventDefault();
   140→        // Only open if there's an active workspace
   141→        if (activeWorkspaceId) {
   142→          openCreateTaskDialog();
   143→        }
   144→        return;
   145→      }
   146→
   147→      if (isEditableShortcutTarget(e.target)) {
   148→        return;
   149→      }
   150→
   151→      if (isShortcutPressed(e, shortcuts.newTab)) {
   152→        e.preventDefault();
   153→        const location = { kind: "documents" } as const;
   154→        openTab({
   155→          navigationState: createTabNavigationState(location, createStackForLocation(location)),
   156→          pinned: false,
   157→        });
   158→        return;
   159→      }
   160→
   161→      const { activeTabId: currentTabId, tabIds, tabCount } = tabStateRef.current;
   162→
   163→      if (isShortcutPressed(e, shortcuts.closeTab)) {
   164→        if (!currentTabId || tabCount <= 1) {
   165→          return;
   166→        }
   167→        e.preventDefault();
   168→        closeTab(currentTabId);
   169→        return;
   170→      }
   171→
   172→      const tabSwitchIndex = getTabSwitchIndexFromShortcut(e);
   173→      if (tabSwitchIndex !== null) {
   174→        const targetTabId =
   175→          tabSwitchIndex >= 8
   176→            ? tabIds[tabIds.length - 1]
   177→            : tabIds[tabSwitchIndex];
   178→
   179→        if (!targetTabId) {
   180→          return;
   181→        }
   182→
   183→        e.preventDefault();
   184→        setActiveTab(targetTabId);
   185→        return;
   186→      }
   187→
   188→      // Browser-like shortcut: Reopen Closed Tab
   189→      if (isShortcutPressed(e, shortcuts.reopenClosedTab)) {
   190→        e.preventDefault();
   191→        reopenClosedTab();
   192→      }
   193→    },
   194→    [
   195→      shortcuts.createTask,
   196→      shortcuts.newTab,
   197→      shortcuts.closeTab,
   198→      shortcuts.reopenClosedTab,
   199→      activeWorkspaceId,
   200→      openCreateTaskDialog,
   201→      openTab,
   202→      closeTab,
   203→      setActiveTab,
   204→      reopenClosedTab,
   205→    ]
   206→  );
   207→
   208→  useEffect(() => {
   209→    window.addEventListener("keydown", handleKeyDown);
   210→    return () => window.removeEventListener("keydown", handleKeyDown);
   211→  }, [handleKeyDown]);
   212→}
   213→

