    22→// ─── Hook 1: useTabList ─────────────────────────────────────────────────────
    23→// Returns the tab view model list. Only re-renders when the tabs array changes.
    24→
    25→export function useTabList(): TabViewModel[] {
    26→  const rawTabs = useTabStore((state) => state.tabs);
