    30→// ─── Hook 2: useActiveTabState ──────────────────────────────────────────────
    31→// Returns reactive state about the active tab. Re-renders when active tab changes.
    32→
    33→export interface ActiveTabState {
    34→  activeTabId: string | null;
    35→  activeTab: TabViewModel | null;
    36→  canGoBack: boolean;
    37→  canGoForward: boolean;
    38→  currentUrl: string | null;
    39→  currentNavigationState: TabNavigationState | null;
    40→}
    41→
    42→export function useActiveTabState(): ActiveTabState {
    43→  const activeTabId = useTabStore((state) => state.activeTabId);
    44→  const activeTabRaw = useTabStore((state) =>
    45→    state.tabs.find((tab) => tab.id === state.activeTabId) ?? null
    46→  );
    47→  const canGoBackFn = useTabStore((state) => state.canGoBack);
    48→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
    49→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
    50→  const getCurrentNavigationState = useTabStore(
    51→    (state) => state.getCurrentNavigationState
    52→  );
    53→
    54→  const activeTab = useMemo(
    55→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    56→    [activeTabRaw]
    57→  );
    58→
    59→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    60→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    61→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    62→  const currentNavigationState = activeTabId
    63→    ? getCurrentNavigationState(activeTabId)
    64→    : null;
    65→
    66→  return useMemo(
    67→    () => ({
    68→      activeTabId,
    69→      activeTab,
    70→      canGoBack,
    71→      canGoForward,
    72→      currentUrl,
    73→      currentNavigationState,
    74→    }),
    75→    [activeTabId, activeTab, canGoBack, canGoForward, currentUrl, currentNavigationState]
