    71→/**
    72→ * Get the gateway URL for serving a page
    73→ */
    74→function getPageServeUrl(workspacePath: string, slug: string): string {
    75→  const baseUrl = getGatewayUrl();
    76→  const params = new URLSearchParams({
    77→    workspace_path: workspacePath,
    78→    slug: slug,
    79→  });
    80→  return `${baseUrl}/api/page/serve?${params.toString()}`;
    81→}
