    26→}
    27→
    28→export interface BreadcrumbStackItem {
    29→  id: string;
    30→  label: string;
    31→  icon?: IconData;
    32→  pattern?: string;
    33→  href?: string;
    34→  sourceNodeId?: string;
    35→  parentNodeId?: string;
    36→  meta?: BreadcrumbMeta;
    37→}
    38→
    39→// ─── Cold Start Builder ─────────────────────────────────────────────────────
    40→
    41→export function buildColdStartBreadcrumb(url: string, headers?: NavigateHeaders): BreadcrumbStackItem[] {
    42→  const match = registry.match(url);
    43→  if (!match) return [];
    44→
    45→  const chain: BreadcrumbStackItem[] = [];
    46→
    47→  // 1. Path prefix ancestors
    48→  for (const ancestorPattern of deriveAncestorsFromPrefix(match.pattern)) {
    49→    const ancestorEntry = registry.getEntry(ancestorPattern)!;
    50→    const ancestorParams = pickMatchingParams(ancestorPattern, match.params);
    51→    chain.push(buildBreadcrumbItem(ancestorEntry, ancestorParams));
    52→  }
    53→
    54→  // 2. Rest param intermediate levels
    55→  const restParam = registry.getRestParam(match.pattern);
    56→  if (restParam && match.params[restParam]?.includes("/")) {
    57→    const segments = match.params[restParam].split("/");
    58→    for (let i = 1; i < segments.length; i++) {
    59→      const prefix = segments.slice(0, i).join("/");
    60→      const lastSegment = segments[i - 1];
    61→      chain.push(buildBreadcrumbItem(
    62→        match.entry,
    63→        { ...match.params, [restParam]: prefix },
    64→        { label: humanize(lastSegment) },
    65→      ));
    66→    }
    67→  }
    68→
    69→  // 3. Current node (headers can override label/icon)
    70→  chain.push(buildBreadcrumbItem(match.entry, match.params, headers));
    71→
    72→  return chain;
    73→}
    74→
    75→// ─── Helpers ────────────────────────────────────────────────────────────────
    76→
    77→export function deriveAncestorsFromPrefix(pattern: string): string[] {
    78→  const segments = pattern.split("/").filter(Boolean);
    79→  const ancestors: string[] = [];
    80→
    81→  for (let i = segments.length - 1; i > 0; i--) {
    82→    const candidate = "/" + segments.slice(0, i).join("/");
    83→    if (registry.hasEntry(candidate)) {
    84→      ancestors.unshift(candidate);
    85→    }
    86→  }
    87→  return ancestors;
    88→}
    89→
    90→export function pickMatchingParams(
    91→  targetPattern: string,
    92→  allParams: Record<string, string>,
    93→): Record<string, string> {
    94→  const paramNames = registry.getParamNames(targetPattern);
    95→  const result: Record<string, string> = {};
    96→  for (const name of paramNames) {
    97→    if (allParams[name] !== undefined) {
    98→      result[name] = allParams[name];
    99→    }
   100→  }
   101→  return result;
   102→}
   103→
   104→export function buildBreadcrumbItem(
   105→  entry: RouteEntry,
   106→  params: Record<string, string>,
   107→  headers?: NavigateHeaders,
   108→): BreadcrumbStackItem {
   109→  const href = registry.build(entry.pattern, params);
   110→  const icon = headers?.icon ?? (typeof entry.icon === "function" ? entry.icon(params) : entry.icon);
   111→  const title = typeof entry.title === "function" ? entry.title(params) : entry.title;
   112→
   113→  return {
   114→    id: headers?.id ?? href,
   115→    label: headers?.label ?? title,
   116→    icon,
   117→    pattern: entry.pattern,
   118→    href,
   119→    sourceNodeId: headers?.sourceNodeId,
   120→    parentNodeId: headers?.parentNodeId,
   121→    meta: headers?.meta,
   122→  };
   123→}
